{
  "supported": true,
  "title": "Frozen resource checks",
  "development_plan": [
    "Check energy, legal actions and restart"
  ],
  "state_contract": {
    "energy": "number",
    "attacks": "number"
  },
  "requirements": [
    {
      "id": "R1",
      "text": "Start with 5 energy; attack costs 2",
      "verification": "automated"
    },
    {
      "id": "R2",
      "text": "Insufficient energy cannot attack",
      "verification": "automated"
    },
    {
      "id": "R3",
      "text": "Restart resets energy and attacks",
      "verification": "automated"
    }
  ],
  "tests": [
    {
      "id": "T1",
      "description": "First attack",
      "requirement_ids": [
        "R1"
      ],
      "steps": [
        {
          "action": "assert",
          "source": "state",
          "path": "energy",
          "op": "eq",
          "value": 5
        },
        {
          "action": "click",
          "selector": "#attack"
        },
        {
          "action": "assert",
          "source": "state",
          "path": "energy",
          "op": "eq",
          "value": 3
        },
        {
          "action": "assert",
          "source": "text",
          "selector": "#energy",
          "op": "eq",
          "value": "2"
        }
      ]
    },
    {
      "id": "T2",
      "description": "Repeated attacks, rejected action, restart",
      "requirement_ids": [
        "R1",
        "R2",
        "R3"
      ],
      "steps": [
        {
          "action": "click",
          "selector": "#attack"
        },
        {
          "action": "click",
          "selector": "#attack"
        },
        {
          "action": "assert",
          "source": "state",
          "op": "eq",
          "value": 1,
          "path": "energy"
        },
        {
          "action": "assert",
          "source": "state",
          "op": "eq",
          "value": 2,
          "path": "attacks"
        },
        {
          "action": "click",
          "selector": "#attack"
        },
        {
          "action": "assert",
          "source": "state",
          "op": "eq",
          "value": 1,
          "path": "energy"
        },
        {
          "action": "assert",
          "source": "state",
          "op": "eq",
          "value": 2,
          "path": "attacks"
        },
        {
          "action": "assert",
          "source": "text",
          "op": "eq",
          "value": "1",
          "selector": "#energy"
        },
        {
          "action": "assert",
          "source": "text",
          "op": "eq",
          "value": "2",
          "selector": "#attacks"
        },
        {
          "action": "click",
          "selector": "#restart"
        },
        {
          "action": "assert",
          "source": "state",
          "op": "eq",
          "value": 5,
          "path": "energy"
        },
        {
          "action": "assert",
          "source": "state",
          "op": "eq",
          "value": 0,
          "path": "attacks"
        },
        {
          "action": "assert",
          "source": "text",
          "op": "eq",
